import asyncio
class AsyncIterable:
    def __init__(self):
        self.data = [1, 2, 3]
    def __aiter__(self):
        return self
    async def __anext__(self):
        if not self.data:
            raise StopAsyncIteration
        return self.data.pop(0)
async def main():
    results = []
    async for item in AsyncIterable():
        results.append(item)
    return results
print(asyncio.run(main()))

